'use client';
import { useEffect, useState } from 'react';
import useSWR from 'swr';
import ActivityTree from '@/components/ActivityTree';
import ActivityJsonImporter from '@/components/ActivityJsonImporter';
import TrackingSettings from '@/components/TrackingSettings';
import MailSettings from '@/components/MailSettings';
import { fetchActivityData } from '@/lib/fetchJson';
import { buildTree, collectDescendantIds } from '@/lib/treeUtils';
import type { ActivitiesData, Activity } from '@/lib/types';
import Cookies from 'js-cookie';
import { AlertCircle, Loader2, Edit3, Plus, Save, X } from 'lucide-react';

export default function AdminPage() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [authChecked, setAuthChecked] = useState(false);
  const [pw, setPw] = useState('');
  const [loginError, setLoginError] = useState('');
  const { data, error: loadError, mutate } = useSWR('/api/activities', fetchActivityData, { refreshInterval: 1000 });
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [saveError, setSaveError] = useState('');

  useEffect(() => {
    let active = true;

    fetch('/api/auth/session', { cache: 'no-store' })
      .then((response) => {
        if (!active) return;
        if (response.ok) {
          Cookies.set('cutover_admin', 'true', { expires: 7, path: '/', sameSite: 'strict' });
          setLoggedIn(true);
        } else {
          Cookies.remove('cutover_admin', { path: '/' });
          setLoggedIn(false);
        }
      })
      .catch(() => {
        if (active) setLoggedIn(false);
      })
      .finally(() => {
        if (active) setAuthChecked(true);
      });

    return () => { active = false; };
  }, []);

  const login = async () => {
    setLoginError('');
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pw, role: 'admin' })
    });
    if (res.ok) {
      Cookies.set('cutover_admin', 'true', { expires: 7, path: '/', sameSite: 'strict' });
      setLoggedIn(true);
      setPw('');
    } else {
      const result = await res.json().catch(() => null) as { error?: string } | null;
      setLoginError(result?.error ?? '관리자 비밀번호가 틀렸습니다.');
    }
  };

  const handleUnauthorized = () => {
    Cookies.remove('cutover_admin', { path: '/' });
    setLoggedIn(false);
    setSaveError('');
    setLoginError('관리자 인증이 만료되었습니다. 다시 로그인해 주세요.');
  };

  /**
   * 활동 변경 PUT 한 곳. 응답을 반드시 읽어 실패면 화면에 남긴다.
   * SWR 1초 폴링이 실패한 값을 조용히 되돌리므로, 성공 여부는 이 응답으로만 판단한다.
   */
  const submitActivityChange = async (body: Record<string, unknown>): Promise<boolean> => {
    try {
      const res = await fetch('/api/activities', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const result = await res.json().catch(() => null) as { error?: string } | null;
        if (res.status === 401) {
          handleUnauthorized();
          return false;
        }
        setSaveError(result?.error ?? `변경 사항을 저장하지 못했습니다. (HTTP ${res.status})`);
        return false;
      }

      setSaveError('');
      // 성공한 PUT 은 새 lastUpdated 를 포함한 완전한 ActivitiesData 를 돌려준다. 그것을 그대로
      // 캐시에 넣어야 내 쓰기만큼 스냅샷이 전진한다 — GET 이 실패하는 동안 재요청만 하면 스냅샷이
      // 첫 로드에 멈춰, 혼자 일하는데도 두 번째 저장부터 전부 409(STALE_SNAPSHOT)로 막힌다.
      const result = await res.json().catch(() => null) as ActivitiesData | null;
      if (result) void mutate(result, { revalidate: false });
      else void mutate();
      return true;
    } catch (error) {
      setSaveError(
        `서버에 연결하지 못해 변경 사항을 저장하지 못했습니다. (${error instanceof Error ? error.message : '알 수 없는 네트워크 오류'})`,
      );
      return false;
    }
  };

  const saveDashboardTitle = async () => {
    // 저장이 성공했을 때만 편집을 닫는다. 실패하면 입력한 제목이 그대로 남는다.
    if (await submitActivityChange({ dashboardTitle: editTitle })) setIsEditingTitle(false);
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-[#0A2A66] flex items-center justify-center text-white">
        <Loader2 size={32} className="animate-spin" aria-label="관리자 인증 확인 중" />
      </div>
    );
  }

  if (!loggedIn) {
    return (
      <div className="min-h-screen bg-[#0A2A66] flex items-center justify-center p-6">
        <div className="w-full max-w-[400px] bg-white rounded-3xl p-10 shadow-2xl">
          <div className="text-center mb-10">
            <div className="text-[#EF4444] text-3xl font-bold mb-2 tracking-tight">Korea Credit Bureau.</div>
            <div className="text-2xl font-semibold text-gray-800">Dashboard Admin</div>
            <div className="text-sm text-gray-500 mt-1">관리자 페이지</div>
          </div>

          <input
            type="password"
            placeholder="관리자 비밀번호"
            value={pw}
            onChange={e => setPw(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') void login(); }}
            className="w-full border border-gray-300 rounded-2xl px-6 py-5 text-lg focus:outline-none focus:border-[#0A4B9E]"
          />

          {loginError && <p role="alert" className="mt-3 text-sm text-red-600">{loginError}</p>}

          <button 
            onClick={login} 
            className="mt-6 w-full bg-[#0A4B9E] hover:bg-[#083A7A] py-5 rounded-2xl text-xl font-semibold text-white transition"
          >
            로그인
          </button>
        </div>
      </div>
    );
  }

  const tree = data ? buildTree(data.activities) : [];

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 pb-24">
      <div className="max-w-2xl mx-auto px-5 pt-8">
        <div className="flex justify-between items-center mb-8">
          <div>
            <div className="text-[#EF4444] text-3xl font-bold">KCB</div>
            <div className="text-xl font-semibold">재해복구 모의훈련 대시보드 Admin</div>
          </div>
          <div className="text-sm text-gray-500">
            {new Date().toLocaleString('ko-KR')}
          </div>
        </div>

        {/* 읽기 실패는 저장 실패(admin-save-error)와 원인이 달라 따로 남긴다. */}
        {loadError && (
          <div
            data-testid="admin-load-error"
            role="alert"
            className="mb-6 flex items-start gap-2 rounded-2xl border border-amber-300 bg-amber-50 p-4 font-medium text-amber-900"
          >
            <AlertCircle size={19} className="mt-0.5 flex-shrink-0" />
            <span>
              상황판 데이터를 읽지 못해 아래 내용은 최신이 아닐 수 있습니다.
              {' '}
              ({loadError instanceof Error ? loadError.message : '알 수 없는 읽기 오류'})
            </span>
          </div>
        )}

        {saveError && (
          <div
            data-testid="admin-save-error"
            role="alert"
            className="mb-6 flex items-start gap-2 rounded-2xl border border-red-200 bg-red-50 p-4 font-medium text-red-800"
          >
            <AlertCircle size={19} className="mt-0.5 flex-shrink-0" />
            <span>{saveError}</span>
          </div>
        )}

        {/* 상황판 제목 편집 */}
        <div className="bg-white border border-gray-200 rounded-2xl px-5 py-4 mb-6 shadow-sm">
          <div className="text-xs text-gray-500 mb-2 font-medium">📌 상황판 표시 제목</div>
          {isEditingTitle ? (
            <div className="flex items-center gap-2">
              <input
                type="text"
                data-testid="dashboard-title-input"
                value={editTitle}
                onChange={e => setEditTitle(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') void saveDashboardTitle(); }}
                className="flex-1 border border-blue-300 rounded-xl px-4 py-2 text-lg font-semibold focus:outline-none focus:border-blue-500"
                autoFocus
              />
              <button
                onClick={() => { void saveDashboardTitle(); }}
                className="text-emerald-600 hover:text-emerald-700 p-2"
                title="저장"
              >
                <Save size={20} />
              </button>
              <button
                onClick={() => setIsEditingTitle(false)}
                className="text-gray-500 hover:text-gray-700 p-2"
                title="취소"
              >
                <X size={20} />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <div className="flex-1 text-lg font-semibold text-gray-900">
                {data?.dashboardTitle || '2026 재해복구 모의훈련 대시보드'}
              </div>
import { expect, test, type APIRequestContext, type Page } from '@playwright/test';

const adminPassword = 'e2e-admin-password';

interface Activity {
  id: string;
  parentId: string | null;
  level: number;
  time: string;
  title: string;
  status: string;
}

async function loginAsAdmin(request: APIRequestContext) {
  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
  expect(response.ok()).toBeTruthy();
}

async function readData(request: APIRequestContext): Promise<{ activities: Activity[]; dashboardTitle: string }> {
  return (await request.get('/api/activities')).json();
}

/** 최상위와 하위의 제목이 서로 달라야 확인창이 어느 항목을 가리키는지 구분된다. */
const tree: Activity[] = [
  { id: 'root', parentId: null, level: 1, time: '23:30 ~ 00:40', title: '[E2E] 최상위 작업', status: '대기' },
  { id: 'child', parentId: 'root', level: 2, time: '23:30 ~ 00:00', title: '[E2E] 하위 작업', status: '대기' },
];

let original: { activities: Activity[]; dashboardTitle: string };

test.beforeEach(async ({ request }) => {
  original = await readData(request);
  await loginAsAdmin(request);
  const imported = await request.put('/api/activities', { data: { activities: tree } });
  expect(imported.status(), await imported.text()).toBe(200);
});

test.afterEach(async ({ request }) => {
  await loginAsAdmin(request);
  await request.put('/api/activities', {
    data: { activities: original.activities, dashboardTitle: original.dashboardTitle },
  });
});

async function loginThroughUi(page: Page) {
  await page.goto('/admin');
  await page.getByPlaceholder('관리자 비밀번호').fill(adminPassword);
  await page.getByRole('button', { name: '로그인' }).click();
  await expect(page.getByText('[E2E] 하위 작업', { exact: true })).toBeVisible();
}

/** 트리 행의 상태 드롭다운만. 설정 카드의 select 는 '완료' 옵션이 없다. */
function statusSelects(page: Page) {
  return page.locator('select').filter({ has: page.locator('option[value="완료"]') });
}

/** PUT 만 500 으로 돌려준다. GET(SWR 폴링)은 그대로 통과시킨다. */
async function failEveryPut(page: Page) {
  await page.route('**/api/activities', async (route) => {
    if (route.request().method() !== 'PUT') return route.fallback();
    await route.fulfill({
      status: 500,
      contentType: 'application/json',
      body: JSON.stringify({ error: '상황판 데이터를 저장하지 못했습니다.' }),
    });
  });
}

function waitForPut(page: Page) {
  return page.waitForResponse((r) => r.url().includes('/api/activities') && r.request().method() === 'PUT');
}

test('활동 상태 변경 PUT 이 실패하면 관리 화면에 실패 메시지가 보이고, 성공하면 사라진다', async ({ page }) => {
  await loginThroughUi(page);
  await expect(statusSelects(page)).toHaveCount(2);

  await failEveryPut(page);
  await statusSelects(page).nth(1).selectOption('완료');
  await expect(page.getByTestId('admin-save-error')).toContainText('상황판 데이터를 저장하지 못했습니다.');

  // 가로채기를 풀면 같은 조작이 성공하고 메시지가 사라진다.
  await page.unroute('**/api/activities');
  const putDone = waitForPut(page);
  await statusSelects(page).nth(1).selectOption('지연');
  expect((await putDone).status()).toBe(200);
  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);

  const byId = new Map((await readData(page.request)).activities.map((a) => [a.id, a.status]));
  expect(byId.get('child')).toBe('지연');
});

test('활동 변경이 401 이면 다시 로그인 화면으로 돌아간다', async ({ page }) => {
  await loginThroughUi(page);

  await page.route('**/api/activities', async (route) => {
    if (route.request().method() !== 'PUT') return route.fallback();
    await route.fulfill({
      status: 401,
      contentType: 'application/json',
      body: JSON.stringify({ error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' }),
    });
  });

  await statusSelects(page).nth(1).selectOption('완료');

  await expect(page.getByPlaceholder('관리자 비밀번호')).toBeVisible();
  await expect(page.locator('p[role="alert"]')).toContainText('관리자 인증이 만료되었습니다.');
  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);
});

test('삭제 확인창은 한 번만 뜨고 실제로 지우는 항목의 제목을 보여 준다', async ({ page }) => {
  await loginThroughUi(page);

  const confirmMessages: string[] = [];
  page.on('dialog', async (dialog) => {
    confirmMessages.push(dialog.message());
    await dialog.accept();
  });

  const putDone = waitForPut(page);
  await page.getByTitle('삭제').nth(1).click();
  expect((await putDone).status()).toBe(200);

  expect(confirmMessages).toHaveLength(1);
  expect(confirmMessages[0]).toContain('[E2E] 하위 작업');
  expect(confirmMessages[0]).not.toContain('[E2E] 최상위 작업');

  const remaining = (await readData(page.request)).activities.map((a) => a.id);
  expect(remaining).toEqual(['root']);
});

test('인라인 편집 저장이 실패하면 입력이 닫히지 않고 입력한 값이 남는다', async ({ page }) => {
  await loginThroughUi(page);

  await page.getByTitle('내용 편집').nth(1).click();
  const titleInput = page.getByTestId('activity-edit-title');
  await titleInput.fill('[E2E] 하위 작업 수정본');

  await failEveryPut(page);
  await page.getByTitle('편집 저장').click();
  await expect(page.getByTestId('admin-save-error')).toContainText('상황판 데이터를 저장하지 못했습니다.');
  await expect(titleInput).toHaveValue('[E2E] 하위 작업 수정본');

  // 가로채기를 풀고 다시 저장하면 편집이 닫히고 값이 반영된다.
  await page.unroute('**/api/activities');
  const putDone = waitForPut(page);
  await page.getByTitle('편집 저장').click();
  expect((await putDone).status()).toBe(200);

  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);
  await expect(page.getByTestId('activity-edit-title')).toHaveCount(0);
  await expect(page.getByText('[E2E] 하위 작업 수정본', { exact: true })).toBeVisible();
});

test('상황판 제목 저장이 실패하면 편집이 닫히지 않고 실패 메시지가 보인다', async ({ page }) => {
  await loginThroughUi(page);

  await page.getByTitle('제목 수정').click();
  const titleInput = page.getByTestId('dashboard-title-input');
  await titleInput.fill('[E2E] 상황판 제목');

  await failEveryPut(page);
  await page.getByTitle('저장').click();
  await expect(page.getByTestId('admin-save-error')).toContainText('상황판 데이터를 저장하지 못했습니다.');
  await expect(titleInput).toHaveValue('[E2E] 상황판 제목');

  await page.unroute('**/api/activities');
  const putDone = waitForPut(page);
  await page.getByTitle('저장').click();
  expect((await putDone).status()).toBe(200);

  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);
  await expect(page.getByTestId('dashboard-title-input')).toHaveCount(0);
  await expect(page.getByText('[E2E] 상황판 제목', { exact: true })).toBeVisible();
});
| `+` | 하위 추가 | 이 작업 아래에 `새 액티비티`(시간 `미정`, 상태 `대기`)를 만듭니다. |
| `+` (상위 작업에만) | 같은 레벨 추가 | 맨 아래에 새 상위 작업을 만듭니다. |
| `↑` `↓` | 위로 이동 / 아래로 이동 | 같은 부모 안에서 순서를 바꿉니다. |
| 🗑 | (삭제) | 이 작업과 하위 작업을 지웁니다. 지우는 작업의 제목이 담긴 확인 창이 한 번 뜹니다. |
| ✎ | (편집) | 시간과 제목을 인라인으로 고칩니다(4.4절). |
| 드롭다운 | 상태 | `대기` `진행` `지연` `완료` 중 하나를 고르면 즉시 저장됩니다(4.3절). |

트리 맨 아래의 **최상위 작업 추가** 버튼은 행과 무관하게 항상 있으며, 맨 끝에 새 상위 작업(`새 액티비티`, 시간 `미정`, 상태 `대기`)을 만듭니다. 작업이 하나도 없을 때는 트리 자리에 "등록된 작업이 없습니다" 안내가 뜨는데, 이때도 이 버튼으로 첫 작업을 만들 수 있습니다(`activity.json` 업로드 없이 복구 가능).

### 4.3 상태 바꾸기와 연동 규칙

행 오른쪽 드롭다운에서 상태를 고르면 바로 저장되고, 사용자 화면에는 갱신 주기(`/` 10초, `/pc` 2초) 안에 반영됩니다. 이때 다음 규칙이 자동으로 적용됩니다(`app/admin/page.tsx`).

1. **아래로**: 고른 작업과 그 **하위 작업 전부**가 같은 상태가 됩니다. 상위 작업을 `완료`로 바꾸면 세부 작업도 모두 `완료`가 됩니다.
2. **위로, 진행/대기일 때**: 세부 작업을 `진행` 또는 `대기`로 바꾸면 바로 위 상위 작업이 `진행`이 됩니다.
3. **위로, 완료일 때**: 세부 작업을 `완료`로 바꿨을 때 같은 부모 아래 형제가 모두 `완료`면 상위 작업도 `완료`가 됩니다. 하나라도 남아 있으면 상위 작업은 그대로입니다.
4. `지연`은 위로 전파되지 않습니다. 상위 작업을 `지연`으로 보이게 하려면 상위 작업의 드롭다운에서 직접 고릅니다.

규칙은 바로 위 한 단계까지만 올라갑니다. 3단계 이상 트리에서는 중간 단계만 바뀝니다.

> 규칙 1의 "하위 작업 전부"는 **`parentId`로 이어진 항목**을 하위로 봅니다(삭제 🗑도 같습니다). ID 형식은 상관없으므로 업로드한 `activity.json`의 ID가 `<부모ID>-번호` 꼴이 아니어도(예: 부모 `A`, 자식 `x1`) 그대로 내려갑니다.

### 4.4 제목·시간 편집

**상황판 제목**: 제목 카드의 ✎(제목 수정)를 누르면 입력란이 열립니다. Enter 또는 💾(저장)로 저장, ✕(취소)로 닫습니다. 100자 이하여야 하며, 넘기면 저장되지 않은 채 편집만 닫힙니다.

![상황판 제목 편집 — 입력란과 저장·취소 버튼](assets/guide/admin-title-edit.png)

**작업의 시간·제목**: 행의 ✎를 누르면 시간(위)과 제목(아래) 입력란이 열립니다. 💾로 저장, ✕로 취소합니다. 이 입력란에서는 Enter가 저장이 아니므로 반드시 💾를 누르십시오. 시간은 100자, 제목은 300자 이하이며 비워 둘 수 없습니다.

입력란에는 **✎를 누른 순간 화면에 보이는 값**이 들어갑니다. 콘솔을 열어 둔 채 다른 관리자나 `activity.json` 업로드가 같은 행을 바꿨더라도 그 최신 값에서 고치게 됩니다(입력란을 열어 둔 **뒤에** 들어온 변경은 💾를 누를 때 내 입력으로 덮어씁니다).

![작업 편집 — 첫 행의 시간과 제목이 입력란으로 바뀐 상태](assets/guide/admin-activity-edit.png)

### 4.5 동시 편집 충돌 (`다른 곳에서 상황판이 먼저 바뀌어 저장하지 않았습니다`)

상태 드롭다운과 행 편집(💾)은 콘솔이 들고 있는 작업 목록 **전체**를 한 번에 저장합니다. 그래서 콘솔이 최신 목록을 받지 못한 상태에서 저장하면 그 사이 다른 관리자가 넣은 변경이 전부 옛 값으로 되돌아갈 수 있습니다. 이를 막기 위해 콘솔은 저장할 때 자기 목록의 시점(`lastUpdated`)을 함께 보내고, 서버에 저장된 시점과 다르면 **아무것도 쓰지 않고** `409`로 거절합니다.

- 화면에는 빨간 저장 실패 배너에 `다른 곳에서 상황판이 먼저 바뀌어 저장하지 않았습니다. …`가 나옵니다.
- 이때 저장된 데이터는 **바뀌지 않습니다**. 내가 한 조작은 저장되지 않았으니, 바뀐 값을 확인한 뒤 같은 조작을 다시 하십시오.
- 내 저장은 스스로 막지 않습니다. 콘솔은 저장이 성공할 때마다 서버가 돌려준 새 목록을 그대로 반영하므로, 혼자 작업하는 동안에는 — 노란 읽기 실패 배너(6장)가 떠 있어 1초 폴링이 멈춘 상태라도 — 연속 저장이 그대로 됩니다. 거절은 **다른 곳(다른 관리자 콘솔, 다른 탭, `activity.json` 업로드)에서 실제로 저장이 일어났을 때만** 나옵니다.

import { after, NextRequest, NextResponse } from 'next/server';
import {
  ActivityImportValidationError,
  DEFAULT_DASHBOARD_TITLE,
  readActivityData,
  validateActivityImport,
  writeActivityData,
} from '@/lib/activityData';
import { isAdminRequest } from '@/lib/adminSession';
import { notifyActivityChanges } from '@/lib/mail/service';
import { addActivity, deleteActivity, moveActivity } from '@/lib/treeUtils';
import type { Activity } from '@/lib/types';

export const runtime = 'nodejs';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function unauthorizedResponse() {
  return NextResponse.json(
    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
    { status: 401 },
  );
}

// 분기는 성립했는데 대상 id 가 데이터에 없는 요청. 변경 함수들은 순수 함수 계약대로 무변화 배열을
// 돌려주므로, 여기서 막지 않으면 아무것도 바뀌지 않은 채 새 lastUpdated 와 200 이 나간다 —
// 관리 화면은 res.ok 만 보므로 이미 지워진 행을 건드린 관리자에게 "저장됐다" 로 보인다.
function targetNotFoundResponse(targetId: string) {
  return NextResponse.json(
    {
      error: `대상 작업(${targetId})이 상황판에 없어 변경하지 않았습니다. 다른 곳에서 이미 지웠을 수 있습니다. 목록을 확인한 뒤(화면이 갱신되지 않으면 페이지를 새로 고친 뒤) 다시 시도해 주십시오.`,
      code: 'TARGET_NOT_FOUND',
    },
    { status: 404 },
  );
}

export async function GET() {
  try {
    const data = await readActivityData();
    return NextResponse.json(data, {
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (error) {
    console.error('GET /api/activities failed:', error);
    return NextResponse.json(
      {
        activities: [],
        dashboardTitle: DEFAULT_DASHBOARD_TITLE,
        visitorCount: 0,
        lastUpdated: new Date().toISOString(),
        error: '저장된 상황판 데이터를 읽지 못했습니다.',
      },
      { status: 500 },
    );
  }
}

export async function PUT(request: NextRequest) {
  if (!isAdminRequest(request)) return unauthorizedResponse();

  try {
    const body: unknown = await request.json();
    if (!isRecord(body)) {
      return NextResponse.json({ error: '요청 본문은 JSON 객체여야 합니다.' }, { status: 400 });
    }

    const currentData = await readActivityData();
    let updated: Activity[] = currentData.activities;
    // 어느 변경 분기도 타지 않았는데 조용히 현재 데이터를 다시 저장하면,
    // 관리 화면은 res.ok 만 보므로 틀린 요청이 "저장 성공" 으로 보인다.
    let matched = true;

    if (Array.isArray(body.activities)) {
      // 관리 화면은 자기가 들고 있는 스냅샷 전체를 보낸다. 그 사이 다른 관리자가 쓴 변경을
      // 조용히 옛 값으로 되돌리지 않도록, 스냅샷 시점을 함께 보낸 요청만 충돌로 막는다.
      // 필드가 없는 요청(기존 계약)은 지금까지와 똑같이 그대로 저장된다.
      if (typeof body.expectedLastUpdated === 'string' && body.expectedLastUpdated !== currentData.lastUpdated) {
        return NextResponse.json(
          {
            error: '다른 곳에서 상황판이 먼저 바뀌어 저장하지 않았습니다. 바뀐 내용을 확인한 뒤(화면이 갱신되지 않으면 페이지를 새로 고친 뒤) 다시 시도해 주십시오.',
            code: 'STALE_SNAPSHOT',
          },
          { status: 409 },
        );
      }
      updated = body.activities as Activity[];
    } else if (body.action === 'add' && (typeof body.parentId === 'string' || body.parentId === null)) {
      // parentId === null 은 최상위 추가라 부모가 없는 것이 정상이다. 문자열인데 그 행이 없으면
      // addActivity 가 부모 없는 활동을 만들고 아래 validateActivityImport 가 400
      // 'activity.json 데이터 형식이 올바르지 않습니다.' 를 돌려준다 — 파일 업로드 형식 문제로
      // 읽히는 문구라, 다른 세 분기와 같은 404 로 막는다.
      if (body.parentId !== null && !updated.some((activity) => activity.id === body.parentId)) {
        return targetNotFoundResponse(body.parentId);
      }
      updated = addActivity(updated, body.parentId);
    } else if (body.action === 'delete' && typeof body.targetId === 'string') {
      if (!updated.some((activity) => activity.id === body.targetId)) return targetNotFoundResponse(body.targetId);
      updated = deleteActivity(updated, body.targetId);
    } else if (
      body.action === 'move'
      && typeof body.targetId === 'string'
      && (body.direction === 'up' || body.direction === 'down')
    ) {
      if (!updated.some((activity) => activity.id === body.targetId)) return targetNotFoundResponse(body.targetId);
      updated = moveActivity(updated, body.targetId, body.direction);
    } else if (typeof body.targetId === 'string' && typeof body.newStatus === 'string') {
      if (!updated.some((activity) => activity.id === body.targetId)) return targetNotFoundResponse(body.targetId);
      updated = updated.map((activity) => (
        activity.id === body.targetId ? { ...activity, status: body.newStatus as Activity['status'] } : activity
      ));
    } else {
      matched = false;
    }

    // 제목만 바꾸는 PUT({ dashboardTitle })은 변경 분기가 없는 것이 정상이다.
    if (!matched && body.dashboardTitle === undefined) {
      return NextResponse.json(
        {
          error: '변경할 내용을 알 수 없는 요청입니다. activities 배열, action(add/delete/move), targetId+newStatus 중 하나가 필요합니다.',
          code: 'UNSUPPORTED_ACTION',
        },
        { status: 400 },
      );
    }

    const dashboardTitle = body.dashboardTitle === undefined
      ? currentData.dashboardTitle
      : body.dashboardTitle;
    const validated = validateActivityImport({ activities: updated, dashboardTitle });
    const newData = {
      activities: validated.activities,
      dashboardTitle: validated.dashboardTitle ?? currentData.dashboardTitle,
      lastUpdated: new Date().toISOString(),
      visitorCount: currentData.visitorCount,
    };

    await writeActivityData(newData);
    // 메일은 응답이 나간 뒤 배경에서 보낸다. 릴레이가 죽어 있어도 이 요청은 여기서 끝난다.
    after(() => notifyActivityChanges(currentData.activities, newData.activities, newData.dashboardTitle));
    return NextResponse.json(newData);
  } catch (error) {
    if (error instanceof ActivityImportValidationError) {
      return NextResponse.json(
        { error: error.message, code: 'INVALID_DATA', details: error.issues },
        { status: 400 },
      );
    }

    if (error instanceof SyntaxError) {
      return NextResponse.json({ error: '요청 JSON 문법이 올바르지 않습니다.' }, { status: 400 });
    }

    console.error('PUT /api/activities failed:', error);
    return NextResponse.json({ error: '상황판 데이터를 저장하지 못했습니다.' }, { status: 500 });
  }
}
